struct OnlineBadge: ViewModifier {
    @State private var isOnline = true
    @Environment(\.scenePhase) private var scenePhase

    func body(content: Content) -> some View {
        content
            .overlay(Circle().fill(isOnline ? .green : .red))
            .onChange(of: scenePhase) { isOnline = $0 == .active }
    }
}

extension View {
    func onlineBadge() -> some View { modifier(OnlineBadge()) }
}
